package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class SupportTicketServiceImpl implements SupportTicketService {
 private final SupportTicketRepository repo; private final SupportTicketCommentRepository comments;
 public SupportTicketServiceImpl(SupportTicketRepository r,SupportTicketCommentRepository c){repo=r;comments=c;}
 public List<SupportTicket> my(String u){return repo.findByUserIdOrderByUpdatedAtDesc(u);} public List<SupportTicket> all(){return repo.findAllByOrderByUpdatedAtDesc();}
 public SupportTicket create(SupportTicket t,String u,String n){t.setId(null);t.setUserId(u);t.setEmployeeName(n);t.setStatus("OPEN");t.setTicketNumber(next());String p=t.getPriority()==null?"MEDIUM":t.getPriority();t.setPriority(p);t.setSlaDueAt(LocalDateTime.now().plusHours("URGENT".equals(p)?4:"HIGH".equals(p)?8:"MEDIUM".equals(p)?24:48));return repo.save(t);}
 private String next(){long n=repo.count()+1; return String.format("INC-%06d",n);}
 public SupportTicket update(Long id,SupportTicket x,String u,String role){SupportTicket t=get(id);if(!t.getUserId().equals(u)&&!mgmt(role))throw new IllegalArgumentException("You can only edit your own ticket.");if(!Set.of("OPEN","REOPENED").contains(t.getStatus()))throw new IllegalArgumentException("Only open or reopened tickets can be edited.");t.setSubject(x.getSubject());t.setDescription(x.getDescription());t.setCategory(x.getCategory());t.setPriority(x.getPriority());return repo.save(t);}
 public SupportTicket changeStatus(Long id,String status,String resolution,String actor,String role){if(!mgmt(role))throw new IllegalArgumentException("Support management access required.");if(!Set.of("OPEN","IN_PROGRESS","WAITING_FOR_USER","RESOLVED","CLOSED","REOPENED").contains(status))throw new IllegalArgumentException("Invalid status.");SupportTicket t=get(id);t.setStatus(status);if(resolution!=null&&!resolution.isBlank())t.setResolution(resolution);if("RESOLVED".equals(status)||"CLOSED".equals(status))t.setResolvedAt(LocalDateTime.now());if("REOPENED".equals(status))t.setResolvedAt(null);t.setLastComment(resolution);return repo.save(t);}
 public SupportTicket assign(Long id,String assignee,String team){SupportTicket t=get(id);t.setAssignedTo(assignee);t.setAssignedTeam(team);if("OPEN".equals(t.getStatus()))t.setStatus("IN_PROGRESS");return repo.save(t);}
 public List<SupportTicketComment> comments(Long id){get(id);return comments.findByTicket_IdOrderByCreatedAtAsc(id);}
 public SupportTicketComment addComment(Long id,String u,String n,String text,String role){SupportTicket t=get(id);if(!t.getUserId().equals(u)&&!mgmt(role))throw new IllegalArgumentException("You cannot comment on this ticket.");if(text==null||text.isBlank())throw new IllegalArgumentException("Comment is required.");SupportTicketComment c=new SupportTicketComment();c.setTicket(t);c.setAuthorUserId(u);c.setAuthorName(n);c.setComment(text.trim());t.setLastComment(text.trim());repo.save(t);return comments.save(c);}
 public void delete(Long id,String u,String role){SupportTicket t=get(id);if(!t.getUserId().equals(u)||!"OPEN".equals(t.getStatus()))throw new IllegalArgumentException("Only your open tickets can be deleted.");repo.delete(t);}
 public SupportTicket get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Support ticket not found."));}
 private boolean mgmt(String r){return Set.of("ADMIN","HR","MANAGER").contains(r);}
}
